import { Routes } from '@angular/router';
import { wizardEntryGuard } from './features/quote-wizard/wizard-entry.guard';

export const routes: Routes = [
  {
    path: '',
    pathMatch: 'full',
    loadComponent: () =>
      import('./features/country-selection/country-selection.page').then(
        (m) => m.CountrySelectionPage,
      ),
  },
  {
    path: ':country/quote',
    // countryGuard then switchConfirmGuard, strictly in sequence.
    canActivate: [wizardEntryGuard],
    loadComponent: () =>
      import('./features/quote-wizard/quote-wizard.shell').then((m) => m.QuoteWizardShell),
    children: [
      {
        path: '',
        loadComponent: () =>
          import('./features/quote-wizard/step1-placeholder.page').then(
            (m) => m.Step1PlaceholderPage,
          ),
      },
    ],
  },
  { path: '**', redirectTo: '' },
];
import { inject } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivateFn, Router, UrlTree } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { Country } from '../../core/country/country.model';
import { CountryService, findCountryByCode } from '../../core/country/country.service';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { WizardCountry } from './wizard-country.service';

/** FR-005 / FR-006: only active countries open the wizard; the code is normalised to lower case. */
export const countryGuard: CanActivateFn = async (
  route: ActivatedRouteSnapshot,
): Promise<boolean | UrlTree> => {
  const router = inject(Router);
  const session = inject(QuoteSessionStore);
  const wizardCountry = inject(WizardCountry);
  const countryService = inject(CountryService);
  const param = route.paramMap.get('country') ?? '';
  const lower = param.toLowerCase();

  let countries: Country[];
  try {
    countries = await firstValueFrom(countryService.load());
  } catch {
    wizardCountry.set(null);
    return router.parseUrl('/');
  }

  const country = findCountryByCode(countries, lower);
  if (!country) {
    wizardCountry.set(null);
    session.clear();
    return router.createUrlTree(['/'], { queryParams: { unavailable: lower } });
  }
  if (param !== country.code) {
    return router.createUrlTree(['/', country.code, 'quote']);
  }
  wizardCountry.set(country);
  return true;
};
import { EnvironmentInjector, runInInjectionContext } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { ActivatedRouteSnapshot, Router, RouterStateSnapshot, UrlTree, provideRouter } from '@angular/router';
import { Observable, of, throwError } from 'rxjs';
import { Country } from '../../core/country/country.model';
import { CountryService } from '../../core/country/country.service';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { ConfirmDialogService } from '../../shared/ui/confirm-dialog/confirm-dialog.service';
import { countryGuard } from './country.guard';
import { switchConfirmGuard } from './switch-confirm.guard';
import { wizardEntryGuard } from './wizard-entry.guard';
import { WizardCountry } from './wizard-country.service';

const CO: Country = { code: 'co', name: 'Colombia', legalAge: 18, iconUrl: '/uploads/co.svg', iconAlt: 'Bandera de Colombia' };
const CL: Country = { code: 'cl', name: 'Chile', legalAge: 18, iconUrl: '/uploads/cl.svg', iconAlt: 'Bandera de Chile' };

describe('US-00 · quote wizard entry guards', () => {
  let load: () => Observable<Country[]>;
  let confirm: ReturnType<typeof vi.fn>;
  let session: QuoteSessionStore;
  let wizardCountry: WizardCountry;

  function route(country: string): ActivatedRouteSnapshot {
    return { paramMap: { get: () => country } } as unknown as ActivatedRouteSnapshot;
  }
  const state = {} as RouterStateSnapshot;

  function run(guard: typeof countryGuard, country: string) {
    return runInInjectionContext(TestBed.inject(EnvironmentInjector), () =>
      guard(route(country), state),
    ) as Promise<boolean | UrlTree>;
  }

  function url(result: boolean | UrlTree): string {
    return TestBed.inject(Router).serializeUrl(result as UrlTree);
  }

  beforeEach(() => {
    sessionStorage.clear();
    load = () => of([CO, CL]);
    confirm = vi.fn();
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        { provide: CountryService, useValue: { load: () => load() } },
        { provide: ConfirmDialogService, useValue: { confirm } },
      ],
    });
    session = TestBed.inject(QuoteSessionStore);
    wizardCountry = TestBed.inject(WizardCountry);
  });

  describe('FR-005 / FR-006 country guard', () => {
    it('lets an active country through and exposes it', async () => {
      expect(await run(countryGuard, 'co')).toBe(true);
      expect(wizardCountry.country()).toEqual(CO);
    });

    it('redirects an upper or mixed case code to the lower case URL', async () => {
      expect(url(await run(countryGuard, 'CO'))).toBe('/co/quote');
      expect(url(await run(countryGuard, 'Cl'))).toBe('/cl/quote');
    });

    it('redirects an unknown country to the selection page with unavailable and clears the session', async () => {
      session.start('co');
      expect(url(await run(countryGuard, 'XX'))).toBe('/?unavailable=xx');
      expect(session.read()).toBeNull();
    });

    it('redirects to the selection page when countries fail to load', async () => {
      load = () => throwError(() => new Error('down'));
      expect(url(await run(countryGuard, 'co'))).toBe('/');
    });
  });

  describe('FR-012 switch confirm guard', () => {
    async function enter(code: string) {
      expect(await run(countryGuard, code)).toBe(true);
      return run(switchConfirmGuard, code);
    }

    it('starts the session without asking when there is no data', async () => {
      session.start('cl');
      expect(await enter('co')).toBe(true);
      expect(confirm).not.toHaveBeenCalled();
      expect(session.lastCountryCode()).toBe('co');
    });

    it('passes without asking for the same country and keeps its data', async () => {
      session.start('co');
      sessionStorage.setItem('quote-session', JSON.stringify({ countryCode: 'co', data: { step1: { a: 'x' } } }));
      expect(await enter('co')).toBe(true);
      expect(confirm).not.toHaveBeenCalled();
      expect(session.hasData()).toBe(true);
    });

    it('asks when another country has data and resets it on confirm', async () => {
      sessionStorage.setItem('quote-session', JSON.stringify({ countryCode: 'cl', data: { step1: { a: 'x' } } }));
      confirm.mockResolvedValue(true);
      expect(await enter('co')).toBe(true);
      expect(confirm).toHaveBeenCalledWith({
        title: '¿Cambiar de país?',
        message: 'Los datos que ingresaste para Chile se van a borrar.',
        confirmLabel: 'Sí, cambiar',
        cancelLabel: 'Seguir en Chile',
      });
      expect(session.lastCountryCode()).toBe('co');
      expect(session.hasData()).toBe(false);
    });

    it('returns to the previous country and keeps its data on cancel', async () => {
      sessionStorage.setItem('quote-session', JSON.stringify({ countryCode: 'cl', data: { step1: { a: 'x' } } }));
      confirm.mockResolvedValue(false);
      expect(url(await enter('co'))).toBe('/cl/quote');
      expect(session.lastCountryCode()).toBe('cl');
      expect(session.hasData()).toBe(true);
    });
  });

  describe('composed entry guard', () => {
    it('does not ask or touch the session when the country is invalid', async () => {
      sessionStorage.setItem('quote-session', JSON.stringify({ countryCode: 'cl', data: { step1: { a: 'x' } } }));
      const result = await run(wizardEntryGuard, 'zz');
      expect(url(result)).toBe('/?unavailable=zz');
      expect(confirm).not.toHaveBeenCalled();
    });
  });
});
import { TestBed } from '@angular/core/testing';
import { Router, provideRouter } from '@angular/router';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { ConfirmDialogService } from '../../shared/ui/confirm-dialog/confirm-dialog.service';
import { QuoteWizardShell } from './quote-wizard.shell';
import { WizardCountry } from './wizard-country.service';

describe('US-00 · FR-007 header "Cambiar país"', () => {
  let confirm: ReturnType<typeof vi.fn>;
  let navigate: ReturnType<typeof vi.spyOn>;
  let session: QuoteSessionStore;

  function setup(data: Record<string, unknown>) {
    sessionStorage.setItem('quote-session', JSON.stringify({ countryCode: 'co', data }));
    const fixture = TestBed.createComponent(QuoteWizardShell);
    fixture.detectChanges();
    return fixture;
  }

  async function clickChange(fixture: ReturnType<typeof setup>) {
    const button = Array.from(
      (fixture.nativeElement as HTMLElement).querySelectorAll('button'),
    ).find((b) => b.textContent?.trim() === 'Cambiar país');
    button?.click();
    await fixture.whenStable();
    await Promise.resolve();
  }

  beforeEach(() => {
    sessionStorage.clear();
    confirm = vi.fn();
    TestBed.configureTestingModule({
      providers: [provideRouter([]), { provide: ConfirmDialogService, useValue: { confirm } }],
    });
    TestBed.inject(WizardCountry).set({
      code: 'co',
      name: 'Colombia',
      legalAge: 18,
      iconUrl: '/uploads/co.svg',
      iconAlt: 'Bandera de Colombia',
    });
    session = TestBed.inject(QuoteSessionStore);
    navigate = vi.spyOn(TestBed.inject(Router), 'navigate').mockResolvedValue(true);
  });

  it('shows the active country flag and name', () => {
    const fixture = setup({});
    const el = fixture.nativeElement as HTMLElement;
    expect(el.querySelector('img')?.getAttribute('alt')).toBe('');
    expect(el.querySelector('.wizard-header__country-name')?.textContent).toContain('Colombia');
  });

  it('keeps the country name visible when the country has no icon', () => {
    TestBed.inject(WizardCountry).set({ code: 'co', name: 'Colombia', legalAge: 18, iconUrl: null, iconAlt: '' });
    const el = setup({}).nativeElement as HTMLElement;
    const country = el.querySelector('.wizard-header__country');
    expect(el.querySelector('img')).toBeNull();
    expect(country?.classList.contains('wizard-header__country--with-icon')).toBe(false);
    expect(el.querySelector('.wizard-header__country-name')?.textContent).toContain('Colombia');
  });

  it('goes to the selection page without asking when there is no data', async () => {
    await clickChange(setup({}));
    expect(confirm).not.toHaveBeenCalled();
    expect(navigate).toHaveBeenCalledWith(['/']);
    expect(session.lastCountryCode()).toBe('co');
  });

  it('asks first when there is data, discards it and navigates on confirm', async () => {
    confirm.mockResolvedValue(true);
    await clickChange(setup({ step1: { a: 'x' } }));
    expect(confirm).toHaveBeenCalledWith(
      expect.objectContaining({ message: 'Los datos que ingresaste para Colombia se van a borrar.' }),
    );
    expect(session.hasData()).toBe(false);
    expect(session.lastCountryCode()).toBe('co');
    expect(navigate).toHaveBeenCalledWith(['/']);
  });

  it('stays and keeps the data on cancel', async () => {
    confirm.mockResolvedValue(false);
    await clickChange(setup({ step1: { a: 'x' } }));
    expect(session.hasData()).toBe(true);
    expect(navigate).not.toHaveBeenCalled();
  });
});
import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { Router, RouterOutlet } from '@angular/router';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { ConfirmDialogService } from '../../shared/ui/confirm-dialog/confirm-dialog.service';
import { WizardCountry } from './wizard-country.service';

@Component({
  selector: 'app-quote-wizard-shell',
  imports: [RouterOutlet],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './quote-wizard.shell.html',
  styleUrl: './quote-wizard.shell.scss',
})
export class QuoteWizardShell {
  protected readonly wizardCountry = inject(WizardCountry);
  private readonly session = inject(QuoteSessionStore);
  private readonly confirmDialog = inject(ConfirmDialogService);
  private readonly router = inject(Router);

  /** FR-007: leave the wizard; ask first when the session holds data. */
  async changeCountry(): Promise<void> {
    if (this.session.hasData()) {
      const name = this.wizardCountry.country()?.name ?? 'este país';
      const confirmed = await this.confirmDialog.confirm({
        title: '¿Cambiar de país?',
        message: `Los datos que ingresaste para ${name} se van a borrar.`,
        confirmLabel: 'Sí, cambiar',
        cancelLabel: `Seguir en ${name}`,
      });
      if (!confirmed) return;
      this.session.discardData();
    }
    await this.router.navigate(['/']);
  }
}
