import { inject } from '@angular/core';
import { CanActivateFn, Router, UrlTree } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { CountryService, findCountryByCode } from '../../core/country/country.service';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { ConfirmDialogService } from '../../shared/ui/confirm-dialog/confirm-dialog.service';
import { WizardCountry } from './wizard-country.service';

/** FR-012: entering another country with data in session asks before discarding it. Runs after countryGuard. */
export const switchConfirmGuard: CanActivateFn = async (): Promise<boolean | UrlTree> => {
  const router = inject(Router);
  const session = inject(QuoteSessionStore);
  const countryService = inject(CountryService);
  const confirmDialog = inject(ConfirmDialogService);
  const active = inject(WizardCountry).country();
  if (!active) return router.parseUrl('/');

  const previous = session.lastCountryCode();
  if (previous && previous !== active.code && session.hasData()) {
    let previousName = previous.toUpperCase();
    try {
      const countries = await firstValueFrom(countryService.load());
      previousName = findCountryByCode(countries, previous)?.name ?? previousName;
    } catch {
      /* keep the code as the label */
    }
    const confirmed = await confirmDialog.confirm({
      title: '¿Cambiar de país?',
      message: `Los datos que ingresaste para ${previousName} se van a borrar.`,
      confirmLabel: 'Sí, cambiar',
      cancelLabel: `Seguir en ${previousName}`,
    });
    if (!confirmed) return router.createUrlTree(['/', previous, 'quote']);
  }
  session.start(active.code);
  return true;
};
import { Injectable, signal } from '@angular/core';
import { Country } from '../../core/country/country.model';

/** Active country of the wizard, set by the entry guards before the shell renders. */
@Injectable({ providedIn: 'root' })
export class WizardCountry {
  private readonly active = signal<Country | null>(null);
  readonly country = this.active.asReadonly();

  set(country: Country | null): void {
    this.active.set(country);
  }
}
import { EnvironmentInjector, inject, runInInjectionContext } from '@angular/core';
import {
  ActivatedRouteSnapshot,
  CanActivateFn,
  RouterStateSnapshot,
  UrlTree,
} from '@angular/router';
import { countryGuard } from './country.guard';
import { switchConfirmGuard } from './switch-confirm.guard';

/** Runs countryGuard then switchConfirmGuard strictly in sequence (no side effects if the first redirects). */
export const wizardEntryGuard: CanActivateFn = async (
  route: ActivatedRouteSnapshot,
  state: RouterStateSnapshot,
): Promise<boolean | UrlTree> => {
  const injector = inject(EnvironmentInjector);
  const first = await (runInInjectionContext(injector, () =>
    countryGuard(route, state),
  ) as Promise<boolean | UrlTree>);
  if (first !== true) return first;
  return runInInjectionContext(injector, () => switchConfirmGuard(route, state)) as Promise<
    boolean | UrlTree
  >;
};
import { Component, signal } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { beforeEach, describe, expect, it } from 'vitest';
import { SelectFieldComponent, SelectOption } from './select-field.component';

@Component({
  imports: [ReactiveFormsModule, SelectFieldComponent],
  template: `<label for="brand">Marca</label>
    <app-select-field inputId="brand" [options]="options()" [formControl]="control" />`,
})
class HostComponent {
  options = signal<SelectOption[]>([
    { label: 'Alfa', value: 'a' },
    { label: 'Beta', value: 'b' },
    { label: 'Gamma', value: 'c' },
  ]);
  control = new FormControl<string>('', { nonNullable: true });
}

describe('US-01 · FR-011 select field keyboard', () => {
  let fixture: ComponentFixture<HostComponent>;
  let host: HostComponent;
  let trigger: HTMLButtonElement;

  const key = (k: string) => {
    trigger.dispatchEvent(new KeyboardEvent('keydown', { key: k, bubbles: true, cancelable: true }));
    fixture.detectChanges();
  };

  beforeEach(() => {
    fixture = TestBed.createComponent(HostComponent);
    host = fixture.componentInstance;
    fixture.detectChanges();
    trigger = fixture.nativeElement.querySelector('[role="combobox"]');
  });

  it('opens with ArrowDown and updates aria-expanded', () => {
    expect(trigger.getAttribute('aria-expanded')).toBe('false');
    key('ArrowDown');
    expect(trigger.getAttribute('aria-expanded')).toBe('true');
    expect(fixture.nativeElement.querySelectorAll('[role="option"]').length).toBe(3);
  });

  it('moves with arrows (wrapping), Home and End, updating aria-activedescendant', () => {
    key('ArrowDown');
    expect(trigger.getAttribute('aria-activedescendant')).toBe('brand-option-0');
    key('ArrowDown');
    expect(trigger.getAttribute('aria-activedescendant')).toBe('brand-option-1');
    key('End');
    expect(trigger.getAttribute('aria-activedescendant')).toBe('brand-option-2');
    key('ArrowDown');
    expect(trigger.getAttribute('aria-activedescendant')).toBe('brand-option-0');
    key('ArrowUp');
    expect(trigger.getAttribute('aria-activedescendant')).toBe('brand-option-2');
    key('Home');
    expect(trigger.getAttribute('aria-activedescendant')).toBe('brand-option-0');
  });

  it('Enter picks the active option, emits the value and closes', () => {
    key('ArrowDown');
    key('ArrowDown');
    key('Enter');
    expect(host.control.value).toBe('b');
    expect(trigger.getAttribute('aria-expanded')).toBe('false');
    expect(trigger.textContent).toContain('Beta');
  });

  it('Escape closes without changing the value', () => {
    key('ArrowDown');
    key('ArrowDown');
    key('Escape');
    expect(trigger.getAttribute('aria-expanded')).toBe('false');
    expect(host.control.value).toBe('');
  });

  it('writeValue shows the matching label', () => {
    host.control.setValue('c');
    fixture.detectChanges();
    expect(trigger.textContent).toContain('Gamma');
    key('Enter');
    expect(trigger.getAttribute('aria-activedescendant')).toBe('brand-option-2');
  });

  it('is disabled with a message when there are no options', () => {
    host.options.set([]);
    fixture.detectChanges();
    expect(trigger.disabled).toBe(true);
    expect(trigger.textContent).toContain('Sin opciones disponibles');
  });
});
