input.content:
.step1 {
  &__card {
    max-width: 620px;
    margin-top: var(--space-4);
    padding: var(--space-6);
    border-radius: var(--radius-md);
    background: var(--color-surface);
    box-shadow: var(--shadow-card);
  }

  &__heading {
    margin: 0 0 var(--space-1);
    color: var(--color-brand);
    font-size: 24px;
    font-weight: 700;

    &:focus {
      outline: none;
    }

    @media (min-width: 768px) {
      font-size: 32px;
    }
  }

  &__subtitle {
    margin: 0 0 var(--space-6);
    color: var(--color-text-muted);
  }

  &__section {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    margin: var(--space-6) 0 var(--space-3);
    color: var(--color-action);
    font-size: 20px;
    font-weight: 700;
  }

  &__actions {
    margin-top: var(--space-8);
  }

  &__empty {
    margin: 0;
    padding: var(--space-8) var(--space-4);
    color: var(--color-text-muted);
    text-align: center;
  }

  &__error {
    padding: var(--space-4);
    border: 1px solid var(--color-error);
    border-radius: var(--radius-sm);
    background: var(--color-error-bg);
    color: var(--color-error);
    font-weight: 500;

    p {
      margin: 0 0 var(--space-3);
    }
  }

  &__skeleton {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-4);

    @media (min-width: 768px) {
      grid-template-columns: 1fr 1fr;
    }
  }

  &__skeleton-field {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
  }

  &__skeleton-label,
  &__skeleton-control {
    display: block;
    border-radius: 12px 12px 0 0;
    background: var(--color-surface-field-focus);
    animation: step1-pulse 1.4s ease-in-out infinite;
  }

  &__skeleton-label {
    width: 40%;
    height: 14px;
  }

  &__skeleton-control {
    height: 52px;
  }
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  min-height: 48px;
  padding: var(--space-3) var(--space-6);
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  font: inherit;
  font-weight: 700;
  cursor: pointer;

  &:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
  }

  &--cta {
    width: 100%;
    background: var(--color-cta);
    color: var(--color-on-cta);

    &:hover {
      background: var(--color-cta-hover);
    }

    @media (min-width: 576px) {
      width: auto;
      min-width: 200px;
    }
  }

  &--secondary {
    background: var(--color-surface);
    border-color: var(--color-brand);
    color: var(--color-brand);
  }
}

/* First render after load only: items fade up one by one. */
.reveal {
  animation: step1-reveal 600ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
  animation-delay: calc(var(--reveal-index, 0) * 110ms);
}

@keyframes step1-reveal {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes step1-pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reveal,
  .step1__skeleton-label,
  .step1__skeleton-control {
    animation: none;
  }
}

